import { Component } from '@angular/core';
import { Router } from '@angular/router';
import { AuthService } from '../../services/auth.service';

@Component({
  selector: 'app-navbar',
  templateUrl: './navbar.component.html'
})
export class NavbarComponent {
  constructor(public auth: AuthService, private router: Router) {}

  logout() {
    this.auth.logout();
  }

  openTasklist() {
    window.open('http://localhost:8081/camunda/app/tasklist/', '_blank');
  }

  openCockpit() {
    window.open('http://localhost:8081/camunda/app/cockpit/', '_blank');
  }
}
<nav class="navbar" *ngIf="auth.isLoggedIn">
  <div class="nav-brand">
    <span class="logo">&#128188;</span>
    <span class="brand-name">EMP Manager</span>
  </div>

  <div class="nav-links">
    <a *ngIf="auth.isHR" routerLink="/hr-dashboard" routerLinkActive="active">HR Dashboard</a>
    <a *ngIf="auth.isManager" routerLink="/manager-dashboard" routerLinkActive="active">Manager Dashboard</a>
    <a routerLink="/employee-dashboard" routerLinkActive="active">My Profile</a>
  </div>

  <div class="nav-right">
    <span class="role-badge role-{{auth.currentUser?.role?.toLowerCase()}}">
      {{ auth.currentUser?.role }}
    </span>
    <span class="user-name">{{ auth.currentUser?.fullName }}</span>
    <button class="btn-tasklist" (click)="openTasklist()" title="Camunda Tasklist">
      &#9776; Tasklist
    </button>
    <button *ngIf="auth.isHR" class="btn-cockpit" (click)="openCockpit()" title="Camunda Cockpit">
      &#9881; Cockpit
    </button>
    <button class="btn-logout" (click)="logout()">Logout</button>
  </div>
</nav>
